hotNow}/></td><td data-label="Router"><Badge state={row.routerState}/></td><td data-label="Battery"><Badge state={row.batteryState}/><FleetBatterySummary row={row} now={snapshotNow} compact/></td>{view==='helios'&&<td data-label="Victron power"><FleetVictronSummary row={row} now={snapshotNow}/></td>}</>}<td data-label="Location">{row.locationVerified?'Verified':'Review needed'}<small>{row.displayAddress?.label||'Installation address'}: {(row.displayAddress?.text??row.unit.address)||'Not supplied'}</small></td><td data-label="Details"><button data-unit-id={row.id} onClick={()=>open(row.id)}>Details →</button></td></tr>)}</tbody></table>{!filtered.length&&<p>{view==='helios'?'No Helios units match these filters.':view==='stands'?'No stands or support equipment match these filters.':'No linked units match these filters.'}</p>}</div></details>{filteredSource.length>0&&<section className='cos-fleet-source-group cos-fleet-source-group-grid' aria-label='Unlinked equipment in view'><h3>Unlinked equipment · {filteredSource.length}</h3>{filteredSource.slice(0,limit).map(record=><FleetSourceEquipment key={record.id} record={record} now={snapshotNow} estimate={sourcePins.get(record.id)?.estimate} onSelect={sourcePins.has(record.id)?()=>openSource(record.id):undefined}/>)}{filteredSource.length>limit&&<button onClick={()=>setLimit(v=>v+80)}>Show more equipment ({filteredSource.length-limit})</button>}</section>}</>}
