test('existing IT keeps Fleet health and source views without Owner setup controls',async({page})=>{const {app,state}=await mount(page,true);await app.getByRole('navigation',{name:'Fleet dashboard views'}).getByRole('button',{name:/Fleet health/}).click();await expect(app.getByRole('heading',{name:/Fleet health ·/})).toBeVisible();const helios=app.locator('.cos-fleet-table-wrap tbody tr').filter({hasText:'Helios 1'});await expect(helios).toContainText('Lowest reported charge 80%');await expect(helios.locator('td').nth(4)).toContainText('Online');await expect(app.getByRole('navigation',{name:'Fleet dashboard views'}).getByRole('button',{name:/Needs setup/})).toHaveCount(0);await expect(app.getByRole('button',{name:'Register in COS inventory →'})).toHaveCount(0);await openFleetView(app,/Data sources/);await expect(app.getByRole('heading',{name:'How to read this board'})).toBeVisible();expect(state.errors).toEqual([]);});
